class LRUNode:
    def __init__(self, key, value):
        self.key = key
        self.value = value
        self.prev = None
        self.next = None

class LRUCache:
    def __init__(self, capacity):
        self.capacity = capacity
        self.cache = {}
        self.head = LRUNode(None, None)
        self.tail = LRUNode(None, None)
        self.head.next = self.tail
        self.tail.prev = self.head

    def _remove(self, node):
        node.prev.next = node.next
        node.next.prev = node.prev

    def _add_to_front(self, node):
        node.next = self.head.next
        node.prev = self.head
        self.head.next.prev = node
        self.head.next = node

    def get(self, key):
        if key in self.cache:
            node = self.cache[key]
            self._remove(node)
            self._add_to_front(node)
            return node.value
        return -1

    def put(self, key, value):
        if key in self.cache:
            self._remove(self.cache[key])
        node = LRUNode(key, value)
        self._add_to_front(node)
        self.cache[key] = node
        if len(self.cache) > self.capacity:
            lru = self.tail.prev
            self._remove(lru)
            del self.cache[lru.key]

from abc import ABC, abstractmethod
from typing import Dict, Type

class PluginRegistry:
    _plugins: Dict[str, Type["BasePlugin"]] = {}

    @classmethod
    def register(cls, name: str):
        def decorator(plugin_cls: Type["BasePlugin"]):
            if name in cls._plugins:
                raise ValueError(f"Plugin '{name}' already registered")
            cls._plugins[name] = plugin_cls
            return plugin_cls
        return decorator

    @classmethod
    def create(cls, name: str, **kwargs) -> "BasePlugin":
        if name not in cls._plugins:
            available = ", ".join(sorted(cls._plugins.keys()))
            raise KeyError(f"Unknown plugin '{name}'. Available: {available}")
        return cls._plugins[name](**kwargs)

class BasePlugin(ABC):
    @abstractmethod
    def execute(self, data: dict) -> dict:
        pass

    @abstractmethod
    def validate(self, data: dict) -> bool:
        pass

@PluginRegistry.register("transform")
class TransformPlugin(BasePlugin):
    def __init__(self, factor: float = 1.0):
        self.factor = factor

    def execute(self, data: dict) -> dict:
        return {k: v * self.factor for k, v in data.items() if isinstance(v, (int, float))}

    def validate(self, data: dict) -> bool:
        return all(isinstance(v, (int, float)) for v in data.values())

import threading
from concurrent.futures import ThreadPoolExecutor, as_completed
from typing import List, Callable, Any, Dict

class BatchProcessor:
    def __init__(self, max_workers: int = 4):
        self.max_workers = max_workers
        self.lock = threading.Lock()
        self.results: Dict[str, Any] = {}
        self.errors: Dict[str, str] = {}

    def process(self, tasks: Dict[str, Callable[[], Any]]) -> Dict[str, Any]:
        with ThreadPoolExecutor(max_workers=self.max_workers) as executor:
            future_to_name = {
                executor.submit(fn): name
                for name, fn in tasks.items()
            }
            for future in as_completed(future_to_name):
                name = future_to_name[future]
                try:
                    result = future.result(timeout=30)
                    with self.lock:
                        self.results[name] = result
                except Exception as e:
                    with self.lock:
                        self.errors[name] = f"{type(e).__name__}: {e}"
        return self.results

    def summary(self) -> str:
        total = len(self.results) + len(self.errors)
        lines = [f"Processed {total} tasks:"]
        lines.append(f"  Success: {len(self.results)}")
        lines.append(f"  Failed: {len(self.errors)}")
        for name, err in self.errors.items():
            lines.append(f"    {name}: {err}")
        return "\n".join(lines)

