import inspect

class EventEmitter:
    def __init__(self):
        self._listeners: Dict[str, List[Callable]] = {}
        self._once: Dict[str, List[Callable]] = {}

    def on(self, event: str, callback: Callable) -> "EventEmitter":
        if event not in self._listeners:
            self._listeners[event] = []
        self._listeners[event].append(callback)
        return self

    def once(self, event: str, callback: Callable) -> "EventEmitter":
        if event not in self._once:
            self._once[event] = []
        self._once[event].append(callback)
        return self

    def emit(self, event: str, *args: Any, **kwargs: Any) -> bool:
        handlers = self._listeners.get(event, []).copy()
        once_handlers = self._once.pop(event, [])
        handlers.extend(once_handlers)
        if not handlers:
            return False
        for handler in handlers:
            sig = inspect.signature(handler)
            try:
                sig.bind(*args, **kwargs)
                handler(*args, **kwargs)
            except TypeError:
                handler(*args[:len(sig.parameters)])
        return True

    def off(self, event: str, callback: Optional[Callable] = None) -> None:
        if callback is None:
            self._listeners.pop(event, None)
            self._once.pop(event, None)
        elif event in self._listeners:
            self._listeners[event] = [
                cb for cb in self._listeners[event] if cb is not callback
            ]

from typing import Any, Dict, List, Optional, Union

class SchemaError(Exception):
    def __init__(self, path: str, message: str):
        self.path = path
        self.message = message
        super().__init__(f"{path}: {message}")

def validate(data: Any, schema: Dict, path: str = "$") -> List[SchemaError]:
    errors: List[SchemaError] = []
    expected_type = schema.get("type")
    type_map = {"string": str, "integer": int, "float": float, "boolean": bool, "list": list, "dict": dict}

    if expected_type and expected_type in type_map:
        if not isinstance(data, type_map[expected_type]):
            errors.append(SchemaError(path, f"expected {expected_type}, got {type(data).__name__}"))
            return errors

    if expected_type == "dict" and "properties" in schema:
        for key, sub_schema in schema["properties"].items():
            if key not in data:
                if sub_schema.get("required", False):
                    errors.append(SchemaError(f"{path}.{key}", "required field missing"))
            else:
                errors.extend(validate(data[key], sub_schema, f"{path}.{key}"))

    if expected_type == "list" and "items" in schema:
        for i, item in enumerate(data):
            errors.extend(validate(item, schema["items"], f"{path}[{i}]"))

    if "min" in schema and isinstance(data, (int, float)):
        if data < schema["min"]:
            errors.append(SchemaError(path, f"value {data} below minimum {schema['min']}"))

    return errors

