T = TypeVar("T")

@dataclass
class PipelineStep:
    name: str
    transform: Callable[[Any], Any]
    error_handler: Optional[Callable[[Exception], Any]] = None

class Pipeline(Generic[T]):
    def __init__(self):
        self._steps: List[PipelineStep] = []
        self._log: List[str] = []

    def add(self, name: str, transform: Callable, on_error: Optional[Callable] = None) -> "Pipeline[T]":
        self._steps.append(PipelineStep(name, transform, on_error))
        return self

    def execute(self, data: T) -> T:
        result = data
        for step in self._steps:
            try:
                result = step.transform(result)
                self._log.append(f"[OK] {step.name}")
            except Exception as e:
                self._log.append(f"[ERR] {step.name}: {e}")
                if step.error_handler:
                    result = step.error_handler(e)
                else:
                    raise RuntimeError(f"Pipeline failed at '{step.name}': {e}") from e
        return result

    def dry_run(self, data: T) -> List[str]:
        steps = [f"{i+1}. {s.name}" for i, s in enumerate(self._steps)]
        steps.insert(0, f"Pipeline ({len(self._steps)} steps):")
        return steps

    @property
    def log(self) -> List[str]:
        return self._log.copy()

from typing import Any, Dict, Set, Tuple, Optional, Callable
import functools

class TrackedMeta(type):
    _registry: Dict[str, type] = {}

    def __new__(mcs, name: str, bases: Tuple[type, ...], namespace: Dict[str, Any]):
        validators: Dict[str, Callable] = {}
        tracked_attrs: Set[str] = set()

        for key, value in list(namespace.items()):
            if hasattr(value, "_is_validated"):
                validators[key] = value._validator
                tracked_attrs.add(key)

        original_init = namespace.get("__init__")

        def tracked_init(self, *args, **kwargs):
            self._change_log = []
            if original_init:
                original_init(self, *args, **kwargs)

        def tracked_setattr(self, attr: str, value: Any):
            if attr.startswith("_"):
                super(cls, self).__setattr__(attr, value)
                return
            if attr in validators:
                if not validators[attr](value):
                    raise ValueError(f"Validation failed for '{attr}': {value!r}")
            old = getattr(self, attr, "<unset>")
            super(cls, self).__setattr__(attr, value)
            if hasattr(self, "_change_log"):
                self._change_log.append((attr, old, value))

        namespace["__init__"] = tracked_init
        namespace["__setattr__"] = tracked_setattr
        namespace["_validators"] = validators
        namespace["_tracked_attrs"] = tracked_attrs

        cls = super().__new__(mcs, name, bases, namespace)
        mcs._registry[name] = cls
        return cls

def validated(validator: Callable[[Any], bool]):
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            return func(*args, **kwargs)
        wrapper._is_validated = True
        wrapper._validator = validator
        return wrapper
    return decorator

from typing import List, Union, Optional
from dataclasses import dataclass
from enum import Enum, auto

class TokenType(Enum):
    NUMBER = auto()
    PLUS = auto()
    MINUS = auto()
    STAR = auto()
    SLASH = auto()
    LPAREN = auto()
    RPAREN = auto()
    EOF = auto()

@dataclass
class Token:
    type: TokenType
    value: Optional[float] = None

class Lexer:
    def __init__(self, text: str):
        self.text = text
        self.pos = 0

    def tokenize(self) -> List[Token]:
        tokens: List[Token] = []
        while self.pos < len(self.text):
            ch = self.text[self.pos]
            if ch.isspace():
                self.pos += 1
            elif ch.isdigit() or ch == ".":
                tokens.append(self._read_number())
            elif ch == "+":
                tokens.append(Token(TokenType.PLUS)); self.pos += 1
            elif ch == "-":
                tokens.append(Token(TokenType.MINUS)); self.pos += 1
            elif ch == "*":
                tokens.append(Token(TokenType.STAR)); self.pos += 1
            elif ch == "/":
                tokens.append(Token(TokenType.SLASH)); self.pos += 1
            elif ch == "(":
                tokens.append(Token(TokenType.LPAREN)); self.pos += 1
            elif ch == ")":
                tokens.append(Token(TokenType.RPAREN)); self.pos += 1
            else:
                raise SyntaxError(f"Unexpected character: '{ch}' at position {self.pos}")
        tokens.append(Token(TokenType.EOF))
        return tokens

    def _read_number(self) -> Token:
        start = self.pos
        while self.pos < len(self.text) and (self.text[self.pos].isdigit() or self.text[self.pos] == "."):
            self.pos += 1
        return Token(TokenType.NUMBER, float(self.text[start:self.pos]))

class Parser:
    def __init__(self, tokens: List[Token]):
        self.tokens = tokens
        self.pos = 0

    def parse(self) -> float:
        result = self._expression()
        if self.tokens[self.pos].type != TokenType.EOF:
            raise SyntaxError("Unexpected tokens after expression")
        return result

    def _expression(self) -> float:
        result = self._term()
        while self.tokens[self.pos].type in (TokenType.PLUS, TokenType.MINUS):
            op = self.tokens[self.pos].type
            self.pos += 1
            right = self._term()
            if op == TokenType.PLUS:
                result += right
            else:
                result -= right
        return result

    def _term(self) -> float:
        result = self._factor()
        while self.tokens[self.pos].type in (TokenType.STAR, TokenType.SLASH):
            op = self.tokens[self.pos].type
            self.pos += 1
            right = self._factor()
            if op == TokenType.STAR:
                result *= right
            else:
                if right == 0:
                    raise ZeroDivisionError("Division by zero")
                result /= right
        return result

    def _factor(self) -> float:
        token = self.tokens[self.pos]
        if token.type == TokenType.NUMBER:
            self.pos += 1
            return token.value
        elif token.type == TokenType.LPAREN:
            self.pos += 1
            result = self._expression()
            if self.tokens[self.pos].type != TokenType.RPAREN:
                raise SyntaxError("Expected closing parenthesis")
            self.pos += 1
            return result
        elif token.type == TokenType.MINUS:
            self.pos += 1
            return -self._factor()
        raise SyntaxError(f"Unexpected token: {token}")

from typing import TypeVar, Generic, Callable, Dict, List, Any, Optional, Set
from dataclasses import dataclass, field
import threading
import copy

T = TypeVar("T")

@dataclass
class StateChange(Generic[T]):
    path: str
    old_value: Any
    new_value: Any
    source: str = "unknown"

class ObservableState(Generic[T]):
    def __init__(self, initial: T, deep_copy: bool = True):
        self._state = initial
        self._deep_copy = deep_copy
        self._lock = threading.RLock()
        self._subscribers: Dict[str, List[Callable[[StateChange], None]]] = {}
        self._global_subscribers: List[Callable[[StateChange], None]] = []
        self._middleware: List[Callable[[StateChange], Optional[StateChange]]] = []
        self._history: List[StateChange] = []
        self._max_history = 100

    def get(self, path: str = "") -> Any:
        with self._lock:
            if not path:
                return copy.deepcopy(self._state) if self._deep_copy else self._state
            parts = path.split(".")
            current = self._state
            for part in parts:
                if isinstance(current, dict):
                    current = current[part]
                elif hasattr(current, part):
                    current = getattr(current, part)
                else:
                    raise KeyError(f"Invalid path: '{path}' (failed at '{part}')")
            return copy.deepcopy(current) if self._deep_copy else current

    def set(self, path: str, value: Any, source: str = "unknown") -> None:
        with self._lock:
            old_value = self._resolve_path(path)
            change = StateChange(path=path, old_value=old_value, new_value=value, source=source)
            for mw in self._middleware:
                result = mw(change)
                if result is None:
                    return
                change = result
            self._apply_change(path, change.new_value)
            self._history.append(change)
            if len(self._history) > self._max_history:
                self._history = self._history[-self._max_history:]
            self._notify(change)

    def subscribe(self, callback: Callable[[StateChange], None],
                  path: Optional[str] = None) -> Callable[[], None]:
        with self._lock:
            if path is None:
                self._global_subscribers.append(callback)
                def unsub():
                    with self._lock:
                        self._global_subscribers.remove(callback)
            else:
                if path not in self._subscribers:
                    self._subscribers[path] = []
                self._subscribers[path].append(callback)
                def unsub():
                    with self._lock:
                        self._subscribers[path].remove(callback)
            return unsub

    def _resolve_path(self, path: str) -> Any:
        try:
            return self.get(path)
        except (KeyError, AttributeError):
            return None

    def _apply_change(self, path: str, value: Any) -> None:
        parts = path.split(".")
        current = self._state
        for part in parts[:-1]:
            if isinstance(current, dict):
                current = current[part]
            else:
                current = getattr(current, part)
        if isinstance(current, dict):
            current[parts[-1]] = value
        else:
            setattr(current, parts[-1], value)

    def _notify(self, change: StateChange) -> None:
        for cb in self._global_subscribers:
            cb(change)
        for path, subscribers in self._subscribers.items():
            if change.path == path or change.path.startswith(f"{path}."):
                for cb in subscribers:
                    cb(change)
